variables.lows:
{% set sensors = states.sensor
   | selectattr('attributes.device_class','defined')
   | selectattr('attributes.device_class','equalto','battery')
   | list %}
{% set out = [] %} {% for s in sensors %}
  {% set v = s.state | float(default=9999) %}
  {% if v <= 20 %}
    {% set _ = out.append(s.entity_id) %}
  {% endif %}
{% endfor %} {{ out }}
